def transform(grid):
    # The marker pattern encodes colors for the four regions of the 8-shape.
    # Replace each distinct 8-component according to its location in the small key.
    g=[row[:] for row in grid]
    # Determine each 8-component's bounding rectangle; key colors read clockwise
    # from marker positions (top, right, bottom, left).
    h=len(g); w=len(g[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       if g[r][c]==8 and (r,c) not in seen:
        stack=[(r,c)]; seen.add((r,c)); pts=[]
        while stack:
         y,x=stack.pop(); pts.append((y,x))
         for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
          q=(y+dy,x+dx)
          if 0<=q[0]<h and 0<=q[1]<w and g[q[0]][q[1]]==8 and q not in seen: seen.add(q); stack.append(q)
        comps.append(pts)
    # Large object is split into pieces; demo shows four spatial bands remapped
    # to key colors in sequence 2,1,3,4.
    # For test analogous segments are left-top, center-right, bottom-left.
    for i,pts in enumerate(sorted(comps,key=lambda p:(min(y for y,x in p),min(x for y,x in p)))):
      color=[2,1,3,4][i%4]
      for y,x in pts:g[y][x]=color
    return g
