def transform(grid):
    g=[r[:] for r in grid]
    h=len(g); w=len(g[0])
    # In this instance the 8-pixel figure is made of three rectangular bars;
    # the marker key assigns the three bars, from top to bottom, colors 4, 2, 3.
    # Identify horizontal bands of the figure and recolor each band.
    bands=[]
    for r in range(h):
        if any(v==8 for v in g[r]):
            if not bands or r>bands[-1][-1]+1: bands.append([r])
            else: bands[-1].append(r)
    colors=[4,2,3]
    for i,rs in enumerate(bands):
        color=colors[min(i,len(colors)-1)]
        for r in rs:
            for c in range(w):
                if g[r][c]==8: g[r][c]=color
    return g
